<template>
  <section aria-label="模板版式业务配置" class="template-profile-controls">
    <el-alert v-if="error" :title="error" type="error" :closable="false" />
    <template v-if="readable">
      <div class="format-source"><el-form-item label="版式来源模板"><el-select v-model="sourceId" filterable aria-label="版式来源模板" :disabled="disabled" :loading="loading" placeholder="从已核准模板选择字体与版式" @visible-change="(opened:boolean) => opened && !sources.length && loadSources(null)"><el-option v-for="item in sources" :key="item.template_version" :value="item.template_version" :label="templateDocumentLabels[item.document_type] + ' · ' + item.reason" /><template #footer><el-button v-if="nextAfter" text :loading="loading" @click="loadSources(nextAfter)">加载更多来源模板</el-button></template></el-select></el-form-item><el-button :disabled="disabled || !sourceId || loading" :loading="loading" @click="useSource">采用来源模板的字体与版式</el-button></div>
      <p>来源模板需要处于当前已核准状态。采用操作只复制其固定版式、编号规则、字体与输出类型；章节显示规则继续使用当前模板的章节。</p>
      <el-descriptions :column="1" border><el-descriptions-item label="固定版式">{{ draft.format_revision ? '已登记固定版式版本' : '尚未选择版式' }}</el-descriptions-item><el-descriptions-item label="附件顺序">按照附件要求的声明顺序 · DECLARED_ORDINAL</el-descriptions-item></el-descriptions>
      <el-form-item label="输出类型"><el-checkbox-group v-model="draft.output_types" :disabled="disabled"><el-checkbox label="DOCX" value="DOCX" /><el-checkbox label="PDF" value="PDF" /></el-checkbox-group></el-form-item>
      <rule-basis-editor :model-value="draft.numbering_rule_revision ? [draft.numbering_rule_revision] : []" label="编号规则" resource-kind="RULE" :max-items="1" :basis-names="numberingNames" :disabled="disabled" @update:model-value="value => draft.numbering_rule_revision = value[0] ?? null" />
      <h3>获授权字体</h3><el-table :data="draft.font_artifacts" empty-text="尚未选择获授权字体"><el-table-column label="字体制品" min-width="200"><template #default="{ $index }">固定字体 {{ $index + 1 }}</template></el-table-column><el-table-column label="版本与摘要" min-width="140"><template #default="{ row }"><el-popover trigger="click" width="360"><template #reference><el-button link type="primary">查看固定字体依据</el-button></template><p>{{ row.version_id }}</p><p class="digest">{{ row.content_sha256 }}</p></el-popover></template></el-table-column><el-table-column label="操作" width="100"><template #default="{ $index }"><el-button link type="danger" :disabled="disabled" @click="draft.font_artifacts.splice($index,1)">移除字体</el-button></template></el-table-column></el-table>
      <p>字体的许可、原文件和上游依据在保存及核准时重新核验。来源模板没有提供的字体不能通过填写名称获得使用许可。</p>
      <h3>章节不适用时的显示规则</h3>
      <div v-for="(display,index) in draft.node_displays" :key="index" class="node-display"><div class="display-grid"><el-form-item label="适用章节"><el-select v-model="display.node_id" filterable :disabled="disabled"><el-option v-for="node in catalogue.nodes" :key="node.node_id" :value="node.node_id" :label="(node.official_number ? node.official_number + ' ' : '') + node.title" /></el-select></el-form-item><el-form-item label="不适用时显示"><el-select v-model="display.not_applicable_display" :disabled="disabled"><el-option label="保留适用决定说明" value="SHOW_DECISION" /><el-option label="不输出该章节正文" value="OMIT_BODY" /></el-select></el-form-item></div><rule-basis-editor :model-value="display.rule_revision ? [display.rule_revision] : []" label="章节显示规则" resource-kind="RULE" :max-items="1" :basis-names="display.rule_revision ? {[display.rule_revision.version_id]:'当前章节显示规则'} : {}" :disabled="disabled" @update:model-value="value => display.rule_revision = value[0] ?? null" /><el-button :disabled="disabled" @click="draft.node_displays.splice(index,1)">移除章节显示规则</el-button></div>
      <el-button :disabled="disabled" @click="draft.node_displays.push({node_id:'',not_applicable_display:'SHOW_DECISION',rule_revision:null})">添加章节显示规则</el-button>
      <el-collapse><el-collapse-item title="当前固定版式、字体与编号依据" name="refs"><p v-if="draft.format_revision">版式版本 {{ draft.format_revision.version_id }}；摘要 {{ draft.format_revision.content_sha256 }}</p><p v-if="draft.numbering_rule_revision">编号规则版本 {{ draft.numbering_rule_revision.version_id }}；摘要 {{ draft.numbering_rule_revision.content_sha256 }}</p></el-collapse-item></el-collapse>
      <el-button class="confirm-profile" type="primary" :disabled="disabled || loading" @click="apply">确认版式和输出配置</el-button>
    </template>
  </section>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import useUserStore from '@/store/modules/user'
import RuleBasisEditor from './rule-basis-editor.vue'
import { draftJsonIssue } from './template-collection-input'
import { readBoundedJson } from '@/api/medical/project-json'
import { fail, schemaIssues } from '@/api/medical/protocol'
import type { Basis } from '@/api/medical/protocol'
import { readTemplateDefinition } from '@/api/medical/template-approval'
import { readTemplateDirectory, templateDocumentLabels } from '@/api/medical/template-directory'
import type { TemplateSummary } from '@/api/medical/template-directory'
import type { DefinitionCatalogue } from './template-business-controls'
interface FormatProfile {format_revision:Basis|null;output_types:('DOCX'|'PDF')[];numbering_rule_revision:Basis|null;font_artifacts:Basis[];node_displays:{node_id:string;not_applicable_display:'SHOW_DECISION'|'OMIT_BODY';rule_revision:Basis|null}[];attachment_order:'DECLARED_ORDINAL'}
const props=defineProps<{value:string;disabled:boolean;catalogue:DefinitionCatalogue}>(),emit=defineEmits<{changed:[string]}>()
const user=useUserStore(),draft=ref<FormatProfile>({format_revision:null,output_types:[],numbering_rule_revision:null,font_artifacts:[],node_displays:[],attachment_order:'DECLARED_ORDINAL'}),error=ref(''),readable=ref(true)
const sources=ref<TemplateSummary[]>([]),sourceId=ref(''),nextAfter=ref<string|null>(null),loading=ref(false);let generation=0,controller:AbortController|null=null
const numberingNames=computed(()=>draft.value.numbering_rule_revision?{[draft.value.numbering_rule_revision.version_id]:'当前固定编号规则'}:{})
watch(()=>props.value,text=>{error.value='';if(!text.trim()){draft.value={format_revision:null,output_types:[],numbering_rule_revision:null,font_artifacts:[],node_displays:[],attachment_order:'DECLARED_ORDINAL'};readable.value=true;return}const issue=draftJsonIssue(text);if(issue){error.value=issue;readable.value=false;return}const value=readBoundedJson(text);if(schemaIssues('urn:medical:templates:1.0.0#/$defs/FormatProfile',value).length){error.value='完整版式未通过字段检查，请在高级区域修正。';readable.value=false;return}draft.value=value as unknown as FormatProfile;readable.value=true},{immediate:true})
function clear(){generation++;controller?.abort();controller=null;sources.value=[];sourceId.value='';nextAfter.value=null;loading.value=false;error.value=''}
async function loadSources(after:string|null){const session=user.medicalSession;if(!session||props.disabled||loading.value)return;const current=generation,reading=new AbortController();controller?.abort();controller=reading;loading.value=true;try{const page=await readTemplateDirectory(session,{limit:100,...(after?{after}:{})},reading.signal);if(current!==generation||session!==user.medicalSession)return;const approved=page.items.filter(item=>item.status==='APPROVED');sources.value=after?[...sources.value,...approved]:approved;nextAfter.value=page.next_after}finally{if(current===generation)loading.value=false}}
async function useSource(){const session=user.medicalSession,id=sourceId.value;if(!session||!id||props.disabled||loading.value)return;const current=generation,reading=new AbortController();controller?.abort();controller=reading;loading.value=true;try{const preview=await readTemplateDefinition(session,id,reading.signal);if(current!==generation||session!==user.medicalSession)return;if(preview.template.status!=='APPROVED')fail('REVISION_CONFLICT','来源模板已经发生治理变化，需要重新选择已核准版本');const profile=preview.template.content.format_profile;if(schemaIssues('urn:medical:templates:1.0.0#/$defs/FormatProfile',profile).length)fail('SCHEMA_INVALID','来源模板的字体与版式未通过完整字段检查');const original=structuredClone(profile) as unknown as FormatProfile;draft.value={...draft.value,format_revision:original.format_revision,numbering_rule_revision:original.numbering_rule_revision,font_artifacts:original.font_artifacts,output_types:original.output_types};error.value=''}finally{if(current===generation)loading.value=false}}
function apply(){if(props.disabled||!readable.value||loading.value)return;const value=draft.value;if(schemaIssues('urn:medical:templates:1.0.0#/$defs/FormatProfile',value).length){error.value='请选择完整固定版式、编号规则、至少一种输出类型及获授权字体。';return}const nodes=value.node_displays.map(item=>item.node_id);if(new Set(nodes).size!==nodes.length||nodes.some(id=>!props.catalogue.nodes.some(item=>item.node_id===id))){error.value='章节显示规则需要使用当前模板的实际章节，每个章节分别登记一次。';return}error.value='';emit('changed',JSON.stringify(value,null,2))}
watch(()=>user.medicalSession,clear)
onBeforeUnmount(clear)
</script>
<style scoped>
.template-profile-controls{padding:16px 0}.template-profile-controls p{font-size:12px;color:#526279;line-height:1.8}.template-profile-controls .el-select{width:100%}.format-source{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:20px}.display-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.node-display{padding:20px;border:1px solid #dce3ec;border-radius:8px;margin:16px 0}.template-profile-controls .el-descriptions,.template-profile-controls .el-collapse{margin:20px 0}.confirm-profile{margin-top:20px}.digest{overflow-wrap:anywhere}.template-profile-controls h3{font-size:16px;margin-top:24px}@media(max-width:750px){.format-source,.display-grid{grid-template-columns:1fr}}
</style>
